//! transit-rt: GTFS-realtime, and its joins over the network.
//!
//! The types in [`gtfs_rt`] are generated by `build.rs` from the official
//! `gtfs-realtime.proto` (`proto/`), so decoding follows the spec file.
//! [`overview`] is the flat view (delays, vehicles). [`progress`] joins
//! delays to the schedule: one trip's predicted times and the ranked late
//! view. [`live`] resolves snapshots into the live document
//! (transit-live), so no consumer joins rt by hand. [`encode`] writes and
//! reads the service alerts document as an Alerts feed.
//!
//! Rules:
//!
//! * An rt trip id is a model trip id. A frequency trip's instance is the
//!   descriptor's start_time (`resolve_instance`). An absent start_date
//!   states no date; an unreadable one names no instance.
//! * Stop updates pair by the published stop_sequence (the import's
//!   `Boundary`, else 1..n), and by stop id only without one.
//! * `live_day` is the one place that resolves rt trip ids and an alert's
//!   informed entities (tests/rt_join_law_test, tests/alert_test).
//! * An alert's `direction_id` is one model direction of its route, by
//!   the export's rule (`gtfs_direction` / `model_direction`), because
//!   the spec scopes it to those trips. An entity with no route or an
//!   unknown code names nothing and is counted (D-204).
//! * Encode gives the same bytes for the same document and moment: each
//!   published alert not ended, by id, every translation kept. Read is
//!   its inverse. What cannot be read as written is named (`skipped`,
//!   `dropped`), never guessed. `entity_reading` explains one entity by
//!   the same path (tests/encode_law_test).

pub mod gtfs_rt {
    include!(concat!(env!("OUT_DIR"), "/transit_realtime.rs"));
}

pub mod overview;
pub mod progress;
pub mod live;
pub mod encode;
pub mod load;

pub use overview::{
    AlertView, InformedView,
    decode_overview, RtOverview, StopUpdateView, TripUpdateView, VehicleView,
};
pub use progress::{late_trips, resolve_instance, trip_progress, LateTrip, ProgressStop, StopName, TripProgress};
pub use live::live_day;
pub use encode::{encode_alerts, entity_reading, read_alerts, DroppedAlert, EncodedAlerts, EntityNames, EntityReading, EntityRoute, EntityStop, EntityTrip, ReadAlerts, SkippedEntity};

use prost::Message;

#[derive(Debug, thiserror::Error)]
pub enum RtError {
    #[error("protobuf decode failed: {0}")]
    Decode(#[from] prost::DecodeError),
}

pub type Result<T> = std::result::Result<T, RtError>;

/// Decode a GTFS-rt protobuf payload (the raw bytes an agency serves,
/// typically polled every 15-30 seconds) into a [`gtfs_rt::FeedMessage`].
pub fn decode(bytes: &[u8]) -> Result<gtfs_rt::FeedMessage> {
    Ok(gtfs_rt::FeedMessage::decode(bytes)?)
}
